return {
  apply(ctx) {
    const PROVIDERS = {
      zai: {
        label: 'zai · 智谱 GLM',
        apiKeyEnv: 'ZAI_API_KEY',
        baseURL: 'https://open.bigmodel.cn',
        url: (base) => base.replace(/\/+$/, '') + '/api/monitor/usage/quota/limit',
        header: (key) => 'Authorization: ' + key,
        parse: (json) => {
          const data = json && json.data
          if (!data || !Array.isArray(data.limits)) throw new Error('响应缺少 data.limits')
          return {
            level: data.level,
            limits: data.limits.map((l) => ({
              windowGuess: String(l.unit) === '3' ? '5h' : String(l.unit) === '6' ? 'weekly' : 'unit-' + l.unit,
              usage: l.usage, currentValue: l.currentValue, remaining: l.remaining,
              percentage: l.percentage, nextResetTime: l.nextResetTime,
            })),
          }
        },
      },
      'opencode-go': {
        label: 'opencode-go · OpenCode Zen',
        apiKeyEnv: 'OPENCODE_GO_API_KEY',
        baseURL: 'https://opencode.ai/zen/go',
        url: (base) => base.replace(/\/+$/, '') + '/v1/usage',
        header: (key) => 'Authorization: Bearer ' + key,
        parse: (json) => {
          const usage = json && json.usage
          if (!usage || typeof usage !== 'object') throw new Error('响应缺少 usage')
          const windowOf = (name) => {
            const w = usage[name]
            if (!w || typeof w !== 'object') return undefined
            return { status: w.status, percent: w.percent, resetsAt: w.resetsAt }
          }
          return { windows: { rolling: windowOf('rolling'), weekly: windowOf('weekly'), monthly: windowOf('monthly') } }
        },
      },
      deepseek: {
        label: 'deepseek · 官方 API',
        apiKeyEnv: 'DEEPSEEK_API_KEY',
        baseURL: 'https://api.deepseek.com',
        url: (base) => base.replace(/\/+$/, '') + '/user/balance',
        header: (key) => 'Authorization: Bearer ' + key,
        parse: (json) => {
          if (!json || typeof json !== 'object' || !Array.isArray(json.balance_infos)) throw new Error('响应缺少 balance_infos')
          return {
            isAvailable: json.is_available,
            balanceInfos: json.balance_infos.map((b) => ({ currency: b.currency, totalBalance: b.total_balance, grantedBalance: b.granted_balance, toppedUpBalance: b.topped_up_balance })),
          }
        },
      },
      'qwen-token-plan-cn': {
        label: 'qwen-token-plan-cn · 百炼 Token Plan',
        apiKeyEnv: 'QWEN_TOKEN_PLAN_CN_API_KEY',
        consoleOnly: { code: 'CONSOLE_ONLY', message: '无公开用量 API（仅阿里云控制台可查，需账号登录；API Key 查不到）' },
      },
    }
    const IDS = Object.keys(PROVIDERS)
    const TIMEOUT_MS = 15000

    const resolveKey = async (envName) => {
      const credentials = ctx.get('credentials')
      if (credentials !== undefined) {
        const hit = await credentials.resolve(envName)
        if (hit && typeof hit.value === 'string' && hit.value.length > 0) return hit.value
      }
      return undefined
    }

    const fetchText = async (url, authorizationHeader) => {
      const subprocess = ctx.get('subprocess')
      if (subprocess === undefined) {
        return { fatal: { code: 'NO_SUBPROCESS', message: '运行时没有 subprocess 服务，无法发起查询' } }
      }
      const seconds = Math.max(1, Math.round(TIMEOUT_MS / 1000))
      const spec = {
        argv: ['curl', '--silent', '--show-error', '--location', '--max-time', String(seconds), '-H', authorizationHeader, url],
        cwd: '/',
        stdio: { stdin: 'ignore', stdout: { maxBytes: 65536 }, stderr: { maxBytes: 8192 } },
        graceMs: 2000,
      }
      let handle
      try {
        handle = subprocess.spawn(spec)
      } catch (error) {
        return { fatal: { code: 'SPAWN_ERROR', message: '发起 curl 失败：' + (error && error.message ? error.message : String(error)) } }
      }
      const outcome = await handle.done
      if (outcome.exitCode !== 0) {
        const stderr = handle.collected.stderr.readFrom(0).text || ''
        return { fatal: { code: 'HTTP_ERROR', message: 'curl 退出码 ' + outcome.exitCode, bodySnippet: stderr.slice(0, 200) } }
      }
      return { text: handle.collected.stdout.readFrom(0).text || '' }
    }

    const queryOne = async (provider) => {
      const adapter = PROVIDERS[provider]
      const base = { success: false, provider, queriedAt: new Date().toISOString() }
      if (!adapter) return Object.assign({}, base, { error: { code: 'UNKNOWN_PROVIDER', message: provider } })
      if (adapter.consoleOnly) return Object.assign({}, base, { error: adapter.consoleOnly })
      const apiKey = await resolveKey(adapter.apiKeyEnv)
      if (!apiKey) {
        return Object.assign({}, base, { error: { code: 'MISSING_CREDENTIAL', message: '找不到 ' + adapter.apiKeyEnv + ' 凭证（Web Models 页存储或环境变量）' } })
      }
      const url = adapter.url(adapter.baseURL)
      const { fatal, text } = await fetchText(url, adapter.header(apiKey))
      if (fatal) return Object.assign({}, base, { error: fatal })
      let json
      try {
        json = JSON.parse(text)
      } catch (error) {
        return Object.assign({}, base, { error: { code: 'PARSE_ERROR', message: '响应不是合法 JSON：' + error.message, bodySnippet: text.slice(0, 200) } })
      }
      try {
        return Object.assign({}, base, { success: true, data: adapter.parse(json) })
      } catch (error) {
        return Object.assign({}, base, { error: { code: 'PARSE_ERROR', message: error.message, bodySnippet: text.slice(0, 200) } })
      }
    }

    harness.handle('provider-usage/overview', async () => {
      const providers = []
      for (const provider of IDS) providers.push(await queryOne(provider))
      return { success: true, queriedAt: new Date().toISOString(), providers }
    })
  },
}

