return {
  apply(ctx) {
    const h = React.createElement
    let open = false
    let last = null
    let loading = false
    const listeners = new Set()
    const notify = () => { for (const fn of listeners) fn() }
    const subscribe = (fn) => { listeners.add(fn); return () => { listeners.delete(fn) } }
    const setOpen = (value) => { open = value; notify() }

    const load = () => {
      loading = true; notify();
      host.call('provider-usage/overview', {}).then((res) => {
        last = (res && typeof res === 'object') ? res : { success: false, error: { code: 'BAD_RPC', message: '异常返回' } }
        loading = false; notify()
      }).catch((err) => {
        last = { success: false, error: { code: 'RPC_FAILED', message: String(err && err.message ? err.message : err) } }
        loading = false; notify()
      })
    }

    styles.insert('.pu-foot{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 12px;border:none;border-radius:8px;background:transparent;color:var(--dsw-alias-label-primary);font:inherit;font-size:13px;cursor:pointer;white-space:nowrap}.pu-foot:hover{background:var(--dsw-alias-interactive-bg-hover,var(--dsw-alias-bg-layer-2))}.pu-ic{width:15px;height:15px;display:inline-block}.pu-mask{position:fixed;inset:0;z-index:200;display:flex;align-items:flex-start;justify-content:center;padding:9vh 20px 20px;background:color-mix(in srgb,var(--dsw-alias-bg-layer-0, #000) 45%, transparent)}.pu-panel{width:min(560px,92vw);max-height:70vh;display:flex;flex-direction:column;border:1px solid var(--dsw-alias-border-l2);border-radius:14px;background:var(--dsw-alias-bg-layer-3);box-shadow:0 12px 40px rgb(0 0 0 / .28);overflow:hidden}.pu-head{display:flex;align-items:center;gap:8px;padding:12px 16px;border-bottom:1px solid var(--dsw-alias-border-l2)}.pu-title{flex:1;min-width:0;font-size:14px;font-weight:600;color:var(--dsw-alias-label-primary)}.pu-close{width:26px;height:26px;border:none;border-radius:6px;background:transparent;color:var(--dsw-alias-label-secondary);font-size:13px;cursor:pointer}.pu-close:hover{background:var(--dsw-alias-bg-layer-2)}.pu-tool{display:flex;align-items:center;gap:8px;padding:8px 16px;border-bottom:1px solid var(--dsw-alias-border-l2)}.pu-btn{border:1px solid var(--dsw-alias-border-l2);border-radius:7px;background:var(--dsw-alias-bg-layer-2);color:var(--dsw-alias-label-primary);font:inherit;font-size:12px;line-height:20px;padding:1px 10px;cursor:pointer}.pu-btn:hover{border-color:var(--dsw-alias-brand-primary);color:var(--dsw-alias-brand-primary)}.pu-btn:disabled{opacity:.5;cursor:default}.pu-body{overflow:auto;padding:10px 16px 16px;display:flex;flex-direction:column;gap:8px}.pu-row{border:1px solid var(--dsw-alias-border-l2);border-radius:10px;background:var(--dsw-alias-bg-layer-2);padding:9px 12px}.pu-rowhead{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:500;color:var(--dsw-alias-label-primary)}.pu-badge{flex:none;border-radius:999px;padding:0 8px;font-size:11px;line-height:18px;font-weight:500}.pu-badge.ok{background:var(--dsw-alias-state-success-bg,var(--dsw-alias-bg-module-platform));color:var(--dsw-alias-state-success-primary)}.pu-badge.fail{background:none;color:var(--dsw-alias-label-tertiary)}.pu-pre{margin:8px 0 0;font-size:11px;line-height:1.55;color:var(--dsw-alias-label-secondary);white-space:pre-wrap;word-break:break-all;overflow:hidden}.pu-err{margin:8px 0 0;font-size:12px;line-height:1.5;color:var(--dsw-alias-state-warning-primary,var(--dsw-alias-label-secondary))}.pu-load{font-size:12px;color:var(--dsw-alias-label-tertiary);line-height:1.6}')

    const fmt = (v) => JSON.stringify(v, null, 1)

    const Row = (result) => {
      if (!result) return null
      return h('div', { className: 'pu-row' },
        h('div', { className: 'pu-rowhead' },
          h('span', { className: 'pu-badge ' + (result.success ? 'ok' : 'fail') }, result.success ? 'OK' : '—'),
          h('span', null, result.provider + (result.success ? '' : ' · ' + ((result.error && result.error.code) || ''))),
        ),
        result.success
          ? h('pre', { className: 'pu-pre' }, fmt(result.data))
          : h('div', { className: 'pu-err' }, (result.error && result.error.message) || String(result.error || '未知错误')),
      )
    }

    const Panel = () => {
      const [tick, setTick] = React.useState(0)
      React.useEffect(() => subscribe(() => setTick((t) => t + 1)), [])
      if (!open) return null
      const rows = (last && Array.isArray(last.providers)) ? last.providers : null
      return h('div', { className: 'pu-mask', onClick: () => setOpen(false) },
        h('div', { className: 'pu-panel', onClick: (e) => e.stopPropagation() },
          h('div', { className: 'pu-head' },
            h('span', { className: 'pu-title' }, '模型供应商用量'),
            h('span', { style: { fontSize: 11, color: 'var(--dsw-alias-label-tertiary)' } }, (last && last.queriedAt) ? '更新于 ' + new Date(last.queriedAt).toLocaleTimeString() : ''),
            h('button', { type: 'button', className: 'pu-close', onClick: () => setOpen(false), 'aria-label': '关闭' }, '✕'),
          ),
          h('div', { className: 'pu-tool' },
            h('button', { type: 'button', className: 'pu-btn', disabled: loading, onClick: load }, loading ? '查询中…' : '刷新'),
          ),
          h('div', { className: 'pu-body' },
            loading && !rows ? h('div', { className: 'pu-load' }, '正在查询各供应商用量…') : null,
            rows ? rows.map((r) => h(Row, { key: r.provider, result: r })) : null,
            (!loading && !rows && last && last.error) ? h('div', { className: 'pu-err' }, last.error.code + ': ' + last.error.message) : null,
          ),
        ),
      )
    }

    const slots = ctx.get('slots')
    if (slots === undefined) return

    slots.inject('sidebar.footer.action', () => slots.register(
      { name: 'sidebar.footer.action', id: 'provider-usage-open', order: 10, label: '用量' },
      (props) => {
        const [tick, setTick] = React.useState(0)
        React.useEffect(() => subscribe(() => setTick((t) => t + 1)), [])
        const wide = props && props.wide === true
        return h('button', { type: 'button', className: 'pu-foot', title: '模型供应商用量', 'aria-label': '模型供应商用量', onClick: () => setOpen(!open) },
          h('span', { className: 'pu-ic', 'aria-hidden': true }, '▥'), wide ? h('span', null, '用量') : null)
      },
    ))

    slots.inject('shell.overlay', () => slots.register(
      { name: 'shell.overlay', id: 'provider-usage-popup', order: 10, label: '供应商用量' },
      () => h(Panel, {}),
    ))
  },
}
